// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor1, uint256 amount1, address actor2, uint256 amount2) public {
        vm.assume(actor1 != address(c));
        vm.assume(actor2 != address(c));
        amount1 = bound(amount1, 1, 1e18);
        amount2 = bound(amount2, 1, 1e18);

        vm.deal(actor1, amount1);
        vm.prank(actor1);
        bool ok1;
        try c.addToBalance{value: amount1}() { ok1 = true; } catch { ok1 = false; }
        assertTrue(ok1);

        // Rule: once a deposit succeeds, the contract must accept another deposit from any actor.
        vm.deal(actor2, amount2);
        vm.prank(actor2);
        bool ok2;
        try c.addToBalance{value: amount2}() { ok2 = true; } catch { ok2 = false; }
        assertTrue(ok2, "contract must not stay locked after a successful deposit");
    }
}
